#ifndef FAST_VECTOR_MATH_H
#define FAST_VECTOR_MATH_H

#include <godot_cpp/classes/ref_counted.hpp>
#include <godot_cpp/variant/vector3.hpp>
#include <godot_cpp/variant/packed_vector3_array.hpp>
#include <godot_cpp/variant/array.hpp>

namespace godot {

class FastVectorMath : public RefCounted {
    GDCLASS(FastVectorMath, RefCounted);

protected:
    static void _bind_methods();

public:
    static double dot_product(Vector3 a, Vector3 b);
    static Vector3 cross_product(Vector3 a, Vector3 b);
    static Array compute_centroid_and_bounds(const PackedVector3Array &points);
    static double ray_sphere_intersection(Vector3 origin, Vector3 dir, Vector3 sphere_center, double radius);

    FastVectorMath() = default;
    ~FastVectorMath() = default;
};

} // namespace godot

#endif // FAST_VECTOR_MATH_H

#include "FastVectorMath.h"
#include <godot_cpp/core/class_db.hpp>
#include <limits>
#include <algorithm>

namespace godot {

void FastVectorMath::_bind_methods() {
    ClassDB::bind_static_method("FastVectorMath", D_METHOD("dot_product", "a", "b"), &FastVectorMath::dot_product);
    ClassDB::bind_static_method("FastVectorMath", D_METHOD("cross_product", "a", "b"), &FastVectorMath::cross_product);
    ClassDB::bind_static_method("FastVectorMath", D_METHOD("compute_centroid_and_bounds", "points"), &FastVectorMath::compute_centroid_and_bounds);
    ClassDB::bind_static_method("FastVectorMath", D_METHOD("ray_sphere_intersection", "origin", "dir", "sphere_center", "radius"), &FastVectorMath::ray_sphere_intersection);
}

double FastVectorMath::dot_product(Vector3 a, Vector3 b) {
    return (double)a.dot(b);
}

Vector3 FastVectorMath::cross_product(Vector3 a, Vector3 b) {
    return a.cross(b);
}

Array FastVectorMath::compute_centroid_and_bounds(const PackedVector3Array &points) {
    Array result;
    int32_t len = points.size();
    if (len == 0) {
        result.append(Vector3(0, 0, 0));
        result.append(Vector3(0, 0, 0));
        result.append(Vector3(0, 0, 0));
        return result;
    }
    Vector3 sum;
    Vector3 min_b( std::numeric_limits<real_t>::infinity(),  std::numeric_limits<real_t>::infinity(),  std::numeric_limits<real_t>::infinity());
    Vector3 max_b(-std::numeric_limits<real_t>::infinity(), -std::numeric_limits<real_t>::infinity(), -std::numeric_limits<real_t>::infinity());
    for (int32_t i = 0; i < len; ++i) {
        Vector3 p = points[i];
        sum += p;
        min_b.x = std::min(min_b.x, p.x); min_b.y = std::min(min_b.y, p.y); min_b.z = std::min(min_b.z, p.z);
        max_b.x = std::max(max_b.x, p.x); max_b.y = std::max(max_b.y, p.y); max_b.z = std::max(max_b.z, p.z);
    }
    result.append(sum / (real_t)len);
    result.append(min_b);
    result.append(max_b);
    return result;
}

double FastVectorMath::ray_sphere_intersection(Vector3 origin, Vector3 dir, Vector3 sphere_center, double radius) {
    Vector3 oc = origin - sphere_center;
    real_t a = dir.dot(dir);
    real_t b = 2.0 * oc.dot(dir);
    real_t c = oc.dot(oc) - radius * radius;
    real_t disc = b * b - 4.0 * a * c;
    if (disc < 0.0) return -1.0;
    real_t disc_sqrt = Math::sqrt(disc);
    real_t t1 = (-b - disc_sqrt) / (2.0 * a);
    real_t t2 = (-b + disc_sqrt) / (2.0 * a);
    if (t1 >= 0.0) return (double)t1;
    if (t2 >= 0.0) return (double)t2;
    return -1.0;
}

